{
  "no_answer": false,
  "sentences": [
    {
      "text": "The principal display panel of a medical device must show a word, statement, or other information required by or under authority of the act to appear on the label.",
      "sources": [
        1,
        5
      ]
    }
  ]
}

{
  "no_answer": true,
  "sentences": [
    {
      "text": "Devices that must be directly marked with a unique device identifier are those that cannot be directly marked because it is not technologically feasible, or those that are single-use devices subjected to additional processing and manufacturing for the purpose of an additional single use.",
      "sources": [
        1,
        2
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "Whenever the label of a medical device includes a printed expiration date, date of manufacture, or any other date intended to be brought to the attention of the user of the device, the date must be presented in the following format: The year, using four digits; followed by the month, using two digits; followed by the day, using two digits; each separated by hyphens.",
      "sources": [
        1
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "Stand-alone software that is not distributed in packaged form (e.g., when downloaded from a Web site) is deemed to meet the UDI labeling requirements of this subpart if it complies with the requirements of paragraph (b) of this section and conveys the version number in its production identifier.",
      "sources": [
        1
      ]
    },
    {
      "text": "Stand-alone software that is distributed in both packaged form and in a form that is not packaged (e.g., when downloaded from a Web site) may be identified with the same device identifier.",
      "sources": [
        1
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "Latex condoms must bear an expiration date which is supported by testing as described in paragraphs (d) and (h) of this section.",
      "sources": [
        1,
        2,
        3
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "A labeler may submit a request for an exception from or alternative to the requirement of § 801.20 or any other requirement of this subpart for a specified device or a specified type of device.",
      "sources": [
        1
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "A 510(k) summary shall be in sufficient detail to provide an understanding of the basis for a determination of substantial equivalence.",
      "sources": [
        1,
        2
      ]
    },
    {
      "text": "A 510(k) summary should be in a separate section of the submission, beginning on a new page and ending on a page not shared with any other section of the premarket notification submission, and should be clearly identified as a '510(k) summary.'",
      "sources": [
        1,
        2,
        4
      ]
    },
    {
      "text": "A 510(k) summary for those premarket submissions in which a determination of substantial equivalence is also based on an assessment of performance data shall contain the following information:",
      "sources": [
        1,
        2,
        5
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "Each device manufacturer or importer who initiates a correction or removal of a device that is not required to be reported to FDA under § 806.10 shall keep a record of such correction or removal.",
      "sources": [
        1
      ]
    },
    {
      "text": "Records of corrections and removals not required to be reported to FDA under § 806.10 shall contain the following information:",
      "sources": [
        1,
        4
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "Any establishment within any foreign country engaged in the manufacture, preparation, propagation, compounding, or processing of a device that is imported or offered for import into the United States shall register such establishment and list such devices using the FDA electronic device registration and listing system in conformance with the procedures in this section, § 807.41, and subpart B of this part.",
      "sources": [
        1,
        3
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "A prescription hearing aid shall bear all of the following labeling: (1) Outside package labeling. The outside package of a prescription hearing aid shall bear all of the following:",
      "sources": [
        1,
        4
      ]
    },
    {
      "text": "Labeling, inside the package. The manufacturer or distributor of a prescription hearing aid shall include a user instructional brochure inside the package and shall make an electronic version available for",
      "sources": [
        1,
        2
      ]
    },
    {
      "text": "Labeling on the device. The labeling on a prescription hearing aid itself shall bear all of the following:",
      "sources": [
        1,
        2,
        3
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "An issuing agency must maintain a system for the assignment of unique device identifiers (UDIs) that meets the requirements of § 830.20.",
      "sources": [
        3
      ]
    },
    {
      "text": "An issuing agency must make available information concerning its system for the assignment of UDIs.",
      "sources": [
        3
      ]
    },
    {
      "text": "An issuing agency must maintain a list of labelers that use its system for the assignment of UDIs and provide FDA a copy of such list in electronic form by December 31 of each year.",
      "sources": [
        3
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "Each manufacturer must document and maintain procedures that provide a detailed description of the activities to ensure the integrity, inspection, storage, and operations for labeling and packaging, during the customary conditions of processing, storage, handling, distribution, and, as appropriate, use of the device.",
      "sources": [
        2
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "For OTC drug products intended for oral ingestion, the sodium content per dosage unit must be expressed in milligrams and rounded off to the nearest whole number.",
      "sources": [
        1,
        2,
        3
      ]
    },
    {
      "text": "If the amount of sodium in the labeled maximum daily dose is more than 140 milligrams, a warning must be included in the label stating 'Ask a doctor before use if you have a sodium-restricted diet'.",
      "sources": [
        1,
        1,
        4,
        5
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "The label for over-the-counter and prescription drug products intended for human use administered orally, nasally, rectally, or vaginally, or for use in the area of the eye, containing FD&C Yellow No. 5 as a color additive using the names FD&C Yellow No. 5 and tartrazine.",
      "sources": [
        1
      ]
    },
    {
      "text": "The labels of certain drug products subject to this labeling requirement that are also cosmetics, such as antibacterial mouthwashes and fluoride toothpastes, need not comply with this requirement provided they comply with the requirements of § 701.3 of this chapter.",
      "sources": [
        1
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "The labeling for any prescription drug product to which sulfites have been added as an inactive ingredient, regardless of the amount added, must bear the warning specified in paragraph (b) or (c) of this section.",
      "sources": [
        1
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "Each drug product described in paragraph (b) of this section must have a bar code that contains, at a minimum, the appropriate National Drug Code (NDC) number in a linear bar code that meets European Article Number/Uniform Code Council (EAN/UCC) or Health Industry Business Communications Council (HIBCC) standards or another standard or format that has been approved by the relevant Food and Drug Administration Center Director.",
      "sources": [
        1,
        2
      ]
    },
    {
      "text": "The bar code must appear on the drug's label as defined by section 201(k) of the Federal Food, Drug, and Cosmetic Act.",
      "sources": [
        2
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "21 CFR 211.132 Tamper-evident packaging requirements for over-the-counter (OTC) human drug products. sets out the requirements for tamper-evident packaging of OTC drug products.",
      "sources": [
        1,
        2,
        3,
        4
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "The expiration date of a drug product is determined by appropriate stability testing described in § 211.166.",
      "sources": [
        3
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "Written procedures describing the handling of all written and oral complaints regarding a drug product shall be established and followed.",
      "sources": [
        1,
        2
      ]
    },
    {
      "text": "A written record of each complaint shall be maintained in a file designated for drug product complaints.",
      "sources": [
        1,
        2
      ]
    },
    {
      "text": "Written records involving a drug product shall be maintained until at least 1 year after the expiration date of the drug product, or 1 year after the date that the complaint was received, whichever is longer.",
      "sources": [
        2,
        4
      ]
    }
  ]
}

{
  "no_answer": false,
