    {
      "text": "The quality control unit has the responsibility and authority to approve or reject all components, drug product containers, closures, in-process materials, packaging material, labeling, and drug products, and the authority to review production records to assure that no errors have occurred or, if errors have occurred, that they have been fully investigated.",
      "sources": [
        1
      ]
    },
    {
      "text": "The quality control unit shall be responsible for approving or rejecting all procedures or specifications impacting on the identity, strength, quality, and purity of the drug product.",
      "sources": [
        1
      ]
    },
    {
      "text": "The responsibilities and procedures applicable to the quality control unit shall be in writing; such written procedures shall be followed.",
      "sources": [
        1
      ]
    }
  ]
}

