{
  "no_answer": false,
  "sentences": [
    {
      "text": "The statement of identity shall be presented in bold face type on the principal display panel, shall be in a size reasonably related to the most prominent printed matter on such panel, and shall be in lines generally parallel to the base on which the package rests as it is designed to be displayed.",
      "sources": [
